SET threads TO 1;
ATTACH 'test.db' (ROW_GROUP_SIZE 8192);
USE test;
CREATE TABLE github (
id                     BIGINT,
type                   VARCHAR,
created_at             TIMESTAMP,
actor_id               BIGINT,
actor_login            VARCHAR,
repo_id                BIGINT,
repo_name              VARCHAR,
org_id                 BIGINT,
org_login              VARCHAR,
payload                VARCHAR,
payload_repository_id  BIGINT,
payload_push_id        BIGINT,
payload_size           BIGINT,
payload_distinct_size  BIGINT,
payload_ref            VARCHAR,
payload_action         VARCHAR,
payload_ref_type       VARCHAR,
payload_number         BIGINT
);

PRAGMA enable_profiling='json';
PRAGMA profiling_output='profiler/tables/github.json';
PRAGMA custom_profiling_settings = '{"STATISTICS_SIZE": "true","EXTRA_INFO": "true"}';
COPY github FROM 'gha/github.csv' (FORMAT 'csv', delimiter ',', header 1);
RESET custom_profiling_settings;
PRAGMA enable_profiling='json';

